sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.dashboard-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 20px;
  padding: 20px;
}

.dashboard-summary .tile {
  background: #1f2937;
  color: #fff;
  padding: 25px;
  text-align: center;
  border-radius: 8px;
  font-size: 1.2rem;
  font-weight: bold;
  box-shadow: 0 4px 8px rgba(0,0,0,0.2);
  transition: transform 0.2s ease;
}

.dashboard-summary .tile span {
  display: block;
  font-size: 2rem;
  margin-top: 10px;
  color: #0d6efd;
}

.dashboard-summary .tile:hover {
  transform: scale(1.05);
}

sp_widget.script:
(function() {
  data.counts = {};

  var grEvent = new GlideRecord('x_1790233_event_ma_event_record');
  grEvent.query();
  data.counts.events = grEvent.getRowCount();

  var grTask = new GlideRecord('x_1790233_event_ma_event_task');
  grTask.query();
  data.counts.tasks = grTask.getRowCount();

  var grAttendee = new GlideRecord('x_1790233_event_ma_attendee');
  grAttendee.query();
  data.counts.attendees = grAttendee.getRowCount();

  var grVendor = new GlideRecord('x_1790233_event_ma_vendor');
  grVendor.query();
  data.counts.vendors = grVendor.getRowCount();

  var grBudget = new GlideRecord('x_1790233_event_ma_budget');
  grBudget.query();
  data.counts.budget = grBudget.getRowCount();

  var grSchedule = new GlideRecord('x_1790233_event_ma_schedule');
  grSchedule.query();
  data.counts.schedule = grSchedule.getRowCount();

  var grFeedback = new GlideRecord('x_1790233_event_ma_feedback');
  grFeedback.query();
  data.counts.feedback = grFeedback.getRowCount();
})();
